INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (1, 'The Grand Luminary Ballroom', 'grand-luminary-ballroom', 'Ballrooms', 'Opulent crystal chandeliers and panoramic Arabian Sea views', 'Mumbai', 'Maharashtra', 'Worli Sea Face, South Mumbai', 4.96, 142, 35000.00, 4, 450, 8500, 1, 'Top Rated', 1, 'Pooja Singhania', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=150&auto=format&fit=crop&q=80', 1, '100%', 'within an hour', '["https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=1200&auto=format&fit=crop&q=80"]', '["Valet Parking for 200 Cars", "Concert-Grade Bose Surround Sound", "Intelligent Moving-Head Truss Lighting", "Executive Green Rooms & VIP Dressing Suites", "Private Sea-Facing Cocktail Terrace", "Dedicated Commercial Kitchen Facilities", "Fiber Optic Gigabit WiFi"]', 'An architectural jewel poised along Mumbai''s illustrious Worli coastline. The Grand Luminary Ballroom offers 8,500 square feet of pillar-free luxury with Italian marble finishes and custom Belgian chandeliers.', 'Sound limits apply after 11:30 PM on open terraces. Outside catering permitted with certified luxury vendors.', NOW());
INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (2, 'Skyline Horizon Glass Rooftop', 'skyline-horizon-glass-rooftop', 'Rooftops', '360-degree metropolitan skyline with illuminated glass infinity edge', 'Bengaluru', 'Karnataka', 'Residency Road, Central Business District, Bengaluru', 4.92, 98, 28000.00, 3, 220, 5200, 1, 'Trending', 1, 'Arjun Kapoor', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80', 1, '98%', 'within 30 mins', '["https://images.unsplash.com/photo-1533105079780-92b9be482077?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1517457373958-b7bdd4587205?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1527529482837-4698179dc6ce?w=1200&auto=format&fit=crop&q=80"]', '["360-degree Glass Infinity Perimeter", "Full Circular Artisanal Cocktail Bar", "Weatherproof Retractable Glass Skylight", "Pioneer Pro DJ Console Setup", "Heated Lounge Seating Pods", "Dedicated High-Speed Express Elevator Access"]', 'Perched on the 32nd floor in Bengaluru''s vibrant core, Skyline Horizon merges cosmopolitan glamour with high-altitude tranquility.', 'Non-smoking inside covered areas. Designated sky-lounge smoking terrace available.', NOW());
INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (3, 'Aura Creative Studio & Industrial Loft', 'aura-creative-studio-loft', 'Lofts & Studios', 'Sun-drenched loft with exposed brick and dual cyclorama wall', 'Delhi NCR', 'Delhi', 'The Dhan Mill, Chhatarpur, New Delhi', 4.88, 76, 15000.00, 2, 120, 4200, 0, 'Creator Choice', 1, 'Ananya Sharma', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80', 1, '99%', 'within 15 mins', '["https://images.unsplash.com/photo-1524758631624-e2822e304c36?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1497366216548-37526070297c?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=1200&auto=format&fit=crop&q=80"]', '["24ft White Cyclorama Wall", "Heavy Equipment Ramp Access", "Artisan Cafe & Espresso Bar", "Hair & Makeup Vanity Stations", "Modular Designer Furniture", "Automated Blackout Blinds", "Sonos Surround Audio"]', 'Located inside New Delhi''s artistic compound at Dhan Mill, Chhatarpur, Aura Loft features 20ft ceilings, exposed red brickwork, and north-facing factory windows that bathe the interior in diffuse natural daylight. Perfect for fashion previews, brand workshops, pop-up culinary experiences, and commercial film productions.', 'Clean-up required post event. Equipment load-in strictly through designated loading bay.', NOW());
INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (4, 'The Royal Glasshouse & Botanical Estate', 'royal-glasshouse-botanical-estate', 'Garden Estates', 'Victorian glass conservatory set amidst royal Rajasthani palace gardens', 'Jaipur', 'Rajasthan', 'Amer Palace Road, Kukas, Jaipur', 4.98, 189, 30000.00, 4, 350, 9000, 1, 'Eco-Luxe', 1, 'Jai Singh Rathore', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80', 1, '100%', 'within 2 hours', '["https://images.unsplash.com/photo-1519741497674-611481863552?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1469371670807-013ccf25f16a?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1511285560929-80b456fea0bc?w=1200&auto=format&fit=crop&q=80"]', '["Climate-controlled Glass Conservatory", "Fairy Lighting & Chandelier Canopy", "Sprawling Heritage Royal Lawn", "Bridal Shahi Pavilion", "Parking for 150 Vehicles", "Full Commercial Preparation Kitchen", "Dedicated Royal Concierge Team"]', 'A royal sanctuary in Jaipur surrounded by lush specimen palms, fragrant mogra gardens, and stone lotus fountains. The glass dome allows guests to dine under the desert stars with climate-controlled luxury regardless of season. Revered for destination weddings, luxury brand launches, and anniversary celebrations.', 'Eco-friendly flower petals only. No open fires near botanical foliage.', NOW());
INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (5, 'Vanguard Tech & Convention Auditorium', 'vanguard-convention-auditorium', 'Conference Centers', 'High-tech auditorium with dual 4K LED video walls & breakout suites', 'Hyderabad', 'Telangana', 'Hitec City, Financial District, Hyderabad', 4.91, 110, 40000.00, 4, 600, 12000, 0, 'Enterprise', 1, 'Vikram Reddy', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&auto=format&fit=crop&q=80', 1, '97%', 'within an hour', '["https://images.unsplash.com/photo-1517457373958-b7bdd4587205?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=1200&auto=format&fit=crop&q=80"]', '["Dual 4K LED Screen Walls (40ft)", "Live Streaming Broadcast Studio", "Simultaneous Translation Booths", "High-density Enterprise Mesh WiFi (10Gbps)", "Tiered Ergonomic Executive Seating"]', 'Purpose-built in Cyberabad for cutting-edge technology summits, investor pitch events, and global hybrid symposia.', 'Dedicated AV operator included in booking. Setup access 1 hour prior to event start.', NOW());
INSERT INTO `api_venue` (`id`, `name`, `slug`, `category`, `tagline`, `city`, `state`, `address`, `rating`, `review_count`, `price_per_hour`, `min_hours`, `capacity`, `sqft`, `featured`, `badge`, `verified`, `host_name`, `host_avatar`, `host_is_superhost`, `host_response_rate`, `host_response_time`, `images`, `amenities`, `description`, `rules`, `created_at`) VALUES (6, 'The Bayfront Coastal Pavilion & Yacht Pier', 'bayfront-coastal-pavilion-goa', 'Waterfront', 'Spectacular waterfront event space with private luxury yacht docking', 'Goa', 'Goa', 'Nerul Waterfront, Candolim, North Goa', 4.94, 88, 32000.00, 3, 320, 7200, 1, 'Waterfront', 1, 'Natasha D''Souza', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150&auto=format&fit=crop&q=80', 1, '100%', 'within 30 mins', '["https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=1200&auto=format&fit=crop&q=80"]', '["Private Luxury Yacht Jetty", "Open-air Teak Wood Boardwalk", "Covered Sea Breeze Pavilion", "Tropical Sunset Cocktail Bar"]', 'Nestled along the scenic Nerul river waters in North Goa, blending vibrant coastal energy with contemporary chic architecture.', 'Yacht docking permission must be requested 48 hours prior.', NOW());
INSERT INTO `api_event` (`id`, `title`, `category`, `venue_name`, `city`, `date`, `end_date`, `time`, `end_time`, `schedule_type`, `status`, `schedule_slots`, `price`, `capacity`, `attendees`, `badge`, `image`, `description`, `created_at`, `venue_id`, `organizer_id`) VALUES (101, 'India AI & DeepTech Innovators Summit 2026', 'Technology', 'Vanguard Tech & Convention Auditorium', 'Hyderabad, Telangana', '2026-12-14', '2026-12-15', '09:00 AM', '06:00 PM', 'Multi-Day', 'Published', '[{"time": "09:00 AM - 10:30 AM", "title": "Opening Keynote: Sovereign AI & Autonomous Agents", "speaker": "Dr. Aarav Mehta (DeepMind)"}, {"time": "11:00 AM - 01:00 PM", "title": "Enterprise LLM Scaling & Production Architectures", "speaker": "Panel Discussion"}, {"time": "02:00 PM - 03:45 PM", "title": "DeepTech Founder Showcases & Pitch Sessions", "speaker": "Top 10 Indian AI Startups"}, {"time": "04:15 PM - 06:00 PM", "title": "Gala Networking Dinner & VC Fireside Chat", "speaker": "Key Ecosystem Leaders"}]', 4999.00, 500, 412, 'Almost Sold Out', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&auto=format&fit=crop&q=80', 'Connect with India''s top founders, AI researchers, and venture capitalists exploring the next era of autonomous intelligence and enterprise computing.', NOW(), 5, 1);
